// Raises the Gradle daemon's heap so R8 can minify this app's release build.
//
// Why a plugin: `android/` is generated by Continuous Native Generation, so a
// hand edit to `gradle.properties` is gone on the next `expo prebuild` - and
// the failure it prevents (`R8: java.lang.OutOfMemoryError: Java heap space`)
// only shows up at the very end of a two-hour Android build.
//
// Why the default is not enough: the Expo template ships
// `org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m`, which is fine
// while `minifyEnabled` is off (nothing does whole-program analysis). R8
// rewrites and shrinks every class of React Native, Expo, Firebase, ML Kit and
// the ads/IAP SDKs in one pass, and 2 GB is not enough for this dependency
// set: the release build dies in `:app:minifyReleaseWithR8`.
//
// 6 GB is deliberate headroom for a workstation (19 GB here); the daemon only
// reserves what it uses, so a smaller CI worker is not forced to allocate it.
// Escape hatch: `SETUNO_GRADLE_XMX=-Xmx4g` overrides the heap for a machine
// that cannot afford 6 GB.

const { withGradleProperties } = require("expo/config-plugins")

const JVM_ARGS = "org.gradle.jvmargs"
const DEFAULT_ARGS = "-Xmx6144m -XX:MaxMetaspaceSize=1024m"

/** The heap flag, honouring the escape hatch, or null when it is malformed. */
function jvmArgs() {
  const override = process.env.SETUNO_GRADLE_XMX
  if (!override) return DEFAULT_ARGS
  // Only accept a heap flag: this string goes straight into Gradle's own
  // configuration, so anything else is ignored instead of being passed on.
  return /^-Xmx\d+[mg]$/i.test(override)
    ? `${override} -XX:MaxMetaspaceSize=1024m`
    : DEFAULT_ARGS
}

module.exports = function withAndroidMemory(config) {
  return withGradleProperties(config, (withMods) => {
    const wanted = jvmArgs()
    const existing = withMods.modResults.find(
      (item) => item.type === "property" && item.key === JVM_ARGS,
    )
    if (existing) existing.value = wanted
    else withMods.modResults.push({ type: "property", key: JVM_ARGS, value: wanted })
    return withMods
  })
}
